from pathlib import Path


def _attempts_dir(task_dir: Path) -> Path:
    return task_dir / "attempts"


def count_attempts(task_dir: Path) -> int:
    """Count per-attempt JSONL files in the task's attempts/ subdir."""
    attempts = _attempts_dir(task_dir)
    if not attempts.exists():
        return 0
    return len(list(attempts.glob("attempt-*-*.jsonl")))


def failure_count(task_dir: Path) -> int:
    """Return the number of FAILURE outcomes recorded for this task."""
    count_file = _attempts_dir(task_dir) / "failures.count"
    if not count_file.exists():
        return 0
    try:
        return int(count_file.read_text().strip())
    except (ValueError, OSError):
        return 0


def increment_failure(task_dir: Path) -> int:
    """Increment the failure counter for this task and return the new count."""
    attempts = _attempts_dir(task_dir)
    attempts.mkdir(parents=True, exist_ok=True)
    new_count = failure_count(task_dir) + 1
    (attempts / "failures.count").write_text(str(new_count))
    return new_count

